begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001801','finished.debt@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000001801','00000000-0000-4000-8000-000000001801','finished.debt@example.test','Equipo');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000001801','designer'),('00000000-0000-4000-8000-000000001801','finance'),('00000000-0000-4000-8000-000000001801','operator'),('00000000-0000-4000-8000-000000001801','billing');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000001801';
select public.save_customer('00000000-0000-4000-8000-000000001810',null,'{"display_name":"Cliente deuda terminada"}');
select public.create_direct_order('00000000-0000-4000-8000-000000001820','00000000-0000-4000-8000-000000001810',null,null,'','[{"description":"Listo IVA","quantity":1,"amount":"100","with_vat":true},{"description":"PENDIENTE NO MOSTRAR","quantity":1,"amount":"200"}]','{"amount":"50","paid_on":"1901-01-15","method":"cash"}');
reset role;
update public.orders set created_at=now()-interval '30 days' where id='00000000-0000-4000-8000-000000001820';
set local role authenticated;
select is((public.order_money('00000000-0000-4000-8000-000000001820')->>'due_balance')::numeric,0::numeric,'La ficha de nota no presenta deuda de pendientes');
select is((public.order_money('00000000-0000-4000-8000-000000001820')->>'overdue')::boolean,false,'No hay atraso de producción pendiente aunque tenga 30 días');
select is((public.finance_orders(p_status=>'all',p_id=>'00000000-0000-4000-8000-000000001820')->>'total')::integer,0,'No muestra nota pendiente en Finanzas ni en Todas');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'balance')::numeric,0::numeric,'No hay deuda antes de producir');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001810')->'account'->>'debit')::numeric,0::numeric,'Cuenta corriente no suma trabajos pendientes');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001810')->'account'->>'balance')::numeric,-50::numeric,'La seña permanece a favor, no genera deuda');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001810')->>'credit')::numeric,50::numeric,'Resumen conserva anticipo');
select is(jsonb_array_length(public.billing_order('00000000-0000-4000-8000-000000001820')->'items'),1,'Facturación muestra IVA aun pendiente');
select lives_ok($$select public.mark_order_invoiced('00000000-0000-4000-8000-000000001820')$$,'Permite facturar antes de producir');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'balance')::numeric,0::numeric,'Facturar no crea deuda antes de producción');
select throws_ok($$select public.record_payment('00000000-0000-4000-8000-000000001830','00000000-0000-4000-8000-000000001820',10,'1901-01-15','cash','')$$,'23514',null,'Cobro individual no cobra como deuda lo pendiente');
select public.complete_production('00000000-0000-4000-8000-000000001820',(select id from public.order_items where order_id='00000000-0000-4000-8000-000000001820' and position=1),'');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'balance')::numeric,71::numeric,'Solo terminado con IVA menos seña');
select is((public.finance_orders(p_status=>'overdue',p_id=>'00000000-0000-4000-8000-000000001820')->>'total')::integer,1,'Al terminar se habilita atraso de 15 días desde creación');
select throws_ok($$select public.record_payment('00000000-0000-4000-8000-000000001832','00000000-0000-4000-8000-000000001820',72,'1901-01-15','cash','')$$,'23514',null,'No permite cobrar por nota más que lo terminado');
select is((public.customer_completed_summary('00000000-0000-4000-8000-000000001810')->'orders'->0->>'total')::numeric,121::numeric,'Resumen no expone total de trabajos pendientes');
select ok(position('PENDIENTE NO MOSTRAR' in public.customer_completed_summary('00000000-0000-4000-8000-000000001810')::text)=0,'Ni cuenta corriente ni resumen incluyen texto pendiente');
select public.record_customer_payment('00000000-0000-4000-8000-000000001831','00000000-0000-4000-8000-000000001810',200,'1901-01-15','check','');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'credit')::numeric,129::numeric,'El pago no se consume por trabajos pendientes');
select is((public.finance_customer_payment('00000000-0000-4000-8000-000000001831')->'allocations'->0->>'amount')::numeric,71::numeric,'Imputa solo deuda terminada');
select public.complete_production('00000000-0000-4000-8000-000000001820',null,'');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'balance')::numeric,71::numeric,'Al completar resto se genera deuda y aplica crédito');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'credit')::numeric,0::numeric,'Consume crédito al terminar, no antes');
select is((public.finance_month('1901-01-01')->>'income')::numeric,250::numeric,'Completar y aplicar crédito no duplica ingresos');
select public.complete_production('00000000-0000-4000-8000-000000001820',null,'');
select is((public.finance_customer_account('00000000-0000-4000-8000-000000001810')->>'balance')::numeric,71::numeric,'Repetir cierre no duplica deuda ni crédito');
reset role;
select * from finish();
rollback;
